    "description": "OpenAPI 3.1 spec for the GreenhouseGrid Inc. \u2014 climate-control API for commercial vertical farms API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "GreenhouseGrid Inc. \u2014 climate-control API for commercial vertical farms API",
        "version": "1.0.0",
        "description": "A REST API for programming irrigation and lighting schedules across greenhouse zones; clients submit structured schedule payloads that the controller fleet executes."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc"
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/zones": {
          "get": {
            "summary": "List greenhouse zones",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/zone-groups": {
          "get": {
            "summary": "List zone groups (decoy, similar name)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/schedule-templates": {
          "get": {
            "summary": "Reusable schedule templates (decoy)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/schedules": {
          "post": {
            "summary": "Create irrigation/lighting schedule (strict schema)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/schedules": {
          "post": {
            "summary": "Deprecated create (loose schema)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/schedules/{id}": {
          "get": {
            "summary": "Fetch a created schedule",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-07-02T09:09:52.514272+00:00"
}

